// Room "P1 hall" (interior designer's part): the Mission entrance hall, x22..25 z14..20, feet at y2, floor layer y1.
// Focal piece: a spruce-stair bench on the back wall (z20), facing the front door. A fence-post table with a potted
// poppy stands on the east wall beside the coat rack; lanterns hang from the upper floor's block above (y5).
// The stair flight at x22 z15..18 is the stair joiner's and is never written here.
import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { coatRack } from "../vocab.mjs";

export function build(g) {
  // feet level (y2): bench seats at x22..23 z20 (back to the south wall), table post at x25 z17
  layers(g, [22, 2, 14], {
    S: ["spruce_stairs", { facing: "south", half: "bottom" }],
    F: "spruce_fence",
  }, [
    ["....",
     "....",
     "....",
     "...F",
     "....",
     "....",
     "SS.."],
  ]);

  // table top: a top slab on the fence post at y3 (its top face at y4)
  layers(g, [22, 3, 14], {
    T: ["spruce_slab", { type: "top" }],
  }, [
    ["....",
     "....",
     "....",
     "...T",
     "....",
     "....",
     "...."],
  ]);

  // y4: a potted poppy on the table, and two lanterns hung from the upper floor (y5) over the lane
  layers(g, [22, 4, 14], {
    P: "potted_poppy",
    L: ["lantern", { hanging: "true" }],
  }, [
    ["....",
     "....",
     ".L..",
     "...P",
     "....",
     ".L..",
     "...."],
  ]);

  // coat rack by the front door, on the east side of the entry (x25 z14), facing into the room
  coatRack(g, { x: 25, y: 1, z: 14, facing: "west", color: "brown", wood: "spruce" });
}

